@router.get('/api/avatars/{avatar_id}/metadata')
async def get_avatar_metadata(
    avatar_id: int,
    user: User = Depends(get_current_user)
):
    asset = await AvatarAsset.get_or_none(id=avatar_id, user_id=user.id)
    if not asset:
        raise HTTPException(status_code=404, detail="Avatar asset not found")

    return {
        "avatar_id": asset.id,
        "server_storage_path": asset.file_path,
        "exif_data": asset.exif_metadata,
        "uploaded_at": asset.created_at
    }
